<?php
include "../includes/auth.php"; require_role('admin'); include "../config/database.php";
if(isset($_GET['approve'])){ $id=(int)$_GET['approve']; mysqli_query($conn,"UPDATE users SET status='active' WHERE id=$id AND role='volunteer'"); mysqli_query($conn,"UPDATE volunteers SET approved=1 WHERE user_id=$id"); set_message("Volunteer approved."); header("Location: volunteers.php"); exit(); }
if(isset($_GET['block'])){ $id=(int)$_GET['block']; mysqli_query($conn,"UPDATE users SET status='blocked' WHERE id=$id AND role='volunteer'"); mysqli_query($conn,"UPDATE volunteers SET approved=0 WHERE user_id=$id"); set_message("Volunteer blocked."); header("Location: volunteers.php"); exit(); }
$rows=mysqli_query($conn,"SELECT u.id,u.name,u.email,u.phone,u.status,v.approved FROM users u LEFT JOIN volunteers v ON u.id=v.user_id WHERE u.role='volunteer' ORDER BY u.id DESC"); $pageTitle="Volunteers"; include "../includes/header.php";
?>
<div class="layout"><?php include "../includes/sidebar.php"; ?><section class="content"><h2>Volunteer Management</h2><?php show_message(); ?><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Actions</th></tr><?php while($row=mysqli_fetch_assoc($rows)){ ?><tr><td><?php echo clean($row['name']); ?></td><td><?php echo clean($row['email']); ?></td><td><?php echo clean($row['phone']); ?></td><td><?php echo clean($row['status']); ?></td><td class="actions"><a class="btn small success" href="?approve=<?php echo $row['id']; ?>">Approve</a><a class="btn small danger" href="?block=<?php echo $row['id']; ?>">Block</a></td></tr><?php } ?></table></div></section></div><?php include "../includes/footer.php"; ?>
